from datetime import datetime

# Basic CloudFormation template
template = {
    "Resources": {
        "MyResource": {
            "Type": "AWS::EC2::Instance",
            "Properties": {
                "InstanceType": "t2.micro",
                "ImageId": "ami-0123456789abcdef"
            }
        }
    }
}

# Submit the template using the CloudFormation CLI
cli = CloudFormationCli()
response = cli.submit(
    template=template,
    typeName="XXX::XXX::XXX",
    typeVersion=datetime.now().isoformat(),
    dryRun=True
)

